cd /tmp/claude-0/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/scratchpad/revivalpage-tools; python3 -I - <<'EOF'
p='build.py'; s=open(p).read()
# 1. extra CSS for the glossary box and the wide-screen sidebar
css = r'''
details.words { background: var(--surface); border: 1px solid var(--rule); border-radius: 8px; padding: 8px 14px; font-size: .9rem; min-width: 0; }
details.words > summary { cursor: pointer; color: var(--muted); line-height: 1.4; padding: 2px 0; }
details.words > summary:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
details.words > summary .w-head { font-weight: 700; color: var(--fg); margin-right: .4rem; }
details.words[open] > summary { margin-bottom: .4rem; }
details.words[open] > summary .w-head { display: none; }
details.words section.part { border-top: 0; padding-top: 0; }
details.words section.part h2 { font-size: 1rem; margin: 0 0 .3rem; }
details.words dl.gloss dd { margin-left: 1em; }
@media (min-width: 64rem) {
  .page { display: grid; max-width: 68rem; grid-template-columns: minmax(0, 1fr) 19rem; column-gap: 2.5rem; row-gap: 24px; align-items: start; }
  .page > * { grid-column: 1; min-width: 0; }
  .page > details.words { grid-column: 2; grid-row: 2 / span 2; position: sticky; top: 16px; max-height: calc(100vh - 32px); overflow-y: auto; overscroll-behavior: contain; }
}
</style>'''
s = s.replace("style = re.search(r'<style>.*?</style>', v24, re.S).group(0)\n",
 "style = re.search(r'<style>.*?</style>', v24, re.S).group(0)\nstyle = style[:-len('</style>')].rstrip('\\n') + CSS\n")
s = s.replace("import re, html, sys\n", "import re, html, sys\nCSS = %r\n" % css)
# 2. glossary as details
s = s.replace("""        if h == 'Sources':""", """        if glossary: body.append('</section>'); body.append('</details>'); in_sec = False
        if h == 'Sources':""")
s = s.replace("""        if in_sec: body.append('</section>')
        h = ln[3:]""", """        if in_sec and not glossary: body.append('</section>')
        h = ln[3:]""")
s = s.replace("""        body.append('<section id="%s" class="part">' % sid)
        body.append('<h2>%s</h2>' % inline(h))
        in_sec = True; glossary = h.startswith('8. Words'); continue""",
"""        glossary = h == 'Words used on this page'
        if glossary:
            body.append('<details class="words" id="words">')
            body.append('<summary><span class="w-head">%s</span><span class="w-lead">LEAD</span></summary>' % inline(h))
        body.append('<section id="%s" class="part">' % sid)
        body.append('<h2>%s</h2>' % inline(h))
        in_sec = True; lead_done = False; continue""")
s = s.replace("""    close_list(); body.append('<p>%s</p>' % inline(ln))""",
"""    if glossary and not lead_done:
        i = max(k for k, x in enumerate(body) if 'LEAD' in x)
        body[i] = body[i].replace('LEAD', inline(ln)); lead_done = True; continue
    close_list(); body.append('<p>%s</p>' % inline(ln))""")
s = s.replace("""doc = '\\n'.join([title, style, links, ''] + head + body + ['</div>', '', script, ''])""",
"""opener = "<script>\\nif (window.matchMedia('(min-width: 64rem)').matches) document.getElementById('words').open = true;\\n</script>"
doc = '\\n'.join([title, style, links, ''] + head + body + ['</div>', '', script, opener, ''])""")
open(p,'w').write(s)
EOF
grep -n "glossary\|LEAD\|opener\|CSS" build.py | cut -c1-150; python3 -I build.py

